    ('相差', '这两款手机的价格相差不大，但是功能不一样。', 'khác nhau', 'xiāng chà', '这两款手机的价格相差不大，但是功能不一样。', 'khác nhau', 'xiāng chà', 'Zhè liǎng kuǎn shǒu jī de jià gé xiāng chà bù dà, dàn shì gōng néng bù yī yàng.', 'Giá của hai mẫu điện thoại này chênh lệch không nhiều, nhưng chức năng khác nhau.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-11ac0ba8bb2ac60572fff8fc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-67f09585d26f56750eb72ccf.mp3'),
    ('相声', '我们昨晚去剧场观看了一场精彩的相声表演。', 'một loại hình kịch truyền thống', 'xiàng shēng', '我们昨晚去剧场观看了一场精彩的相声表演。', 'một loại hình kịch truyền thống', 'xiàng shēng', 'Wǒ men zuó wǎn qù jù chǎng guān kàn le yī chǎng jīng cǎi de xiàng shēng biǎo yǎn.', 'Tối qua chúng tôi đến rạp xem một buổi biểu diễn xiangsheng đầy ấn tượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-86c41cf8d3630e52bc450326.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-8d893a082b49aa46540823e8.mp3'),
    ('畜牧', '畜牧业的发展对农村经济起到了积极的推动作用。', 'du mục', 'xù mù', '畜牧业的发展对农村经济起到了积极的推动作用。', 'du mục', 'xù mù', 'Xù mù yè de fā zhǎn duì nóng cūn jīng jì qǐ dào le jī jí de tuī dòng zuò yòng.', 'Phát triển ngành chăn nuôi đã tạo nên động lực tích cực cho kinh tế nông thôn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-9de5adfec653fdf275e5681e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-629840dad0ccc313a1770330.mp3'),
    ('现状', '政府正在努力改善城市的交通现状。', 'hiện trạng', 'xiàn zhuàng', '政府正在努力改善城市的交通现状。', 'hiện trạng', 'xiàn zhuàng', 'Zhèng fǔ zhèng zài nǔ lì gǎi shàn chéng shì de jiāo tōng xiàn zhuàng.', 'Chính phủ đang cố gắng cải thiện hiện trạng giao thông thành phố.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-928457dcaab037f7346be4f4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-540dc6069c00fc5b77f22283.mp3'),
    ('现成', '这些现成的材料可以用来快速完成项目。', 'có sẵn, vốn có', 'xiàn chéng', '这些现成的材料可以用来快速完成项目。', 'có sẵn, vốn có', 'xiàn chéng', 'Zhè xiē xiàn chéng de cái liào kě yǐ yòng lái kuài sù wán chéng xiàng mù.', 'Những vật liệu có sẵn này có thể dùng để hoàn thành dự án nhanh chóng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-5e3fbb3a3a681de00c8dfb5b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0bd189b33f56cf9189807fa1.mp3'),
    ('现场', '记者第一时间赶到事故现场进行报道。', 'hiện trường', 'xiàn chǎng', '记者第一时间赶到事故现场进行报道。', 'hiện trường', 'xiàn chǎng', 'Jì zhě dì yī shí jiān gǎn dào shì gù xiàn chǎng jìn xíng bào dào.', 'Phóng viên đã có mặt tại hiện trường vụ tai nạn để đưa tin kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-edadda6b37008e3b76b7fce8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a52453a6762b8c4001e05e38.mp3'),
    ('狭隘', '狭隘的观念限制了她的发展。', 'hẹp, hẹp hòi', 'xiá ài', '狭隘的观念限制了她的发展。', 'hẹp, hẹp hòi', 'xiá ài', 'Xiá ài de guān niàn xiàn zhì le tā de fā zhǎn.', 'Quan niệm hẹp hòi đã hạn chế sự phát triển của cô ấy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6c8c1abf403e7112fbcf6c37.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-348fda01ab13c7ffbf7bc42e.mp3'),
    ('狭窄', '这条狭窄的小路只允许单车通过。', 'nhỏ hẹp', 'xiá zhǎi', '这条狭窄的小路只允许单车通过。', 'nhỏ hẹp', 'xiá zhǎi', 'Zhè tiáo xiá zhǎi de xiǎo lù zhǐ yǔn xǔ dān chē tōng guò.', 'Con đường nhỏ hẹp này chỉ cho phép xe đạp đi qua.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7e8e47c7ade63dc782d8ec99.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-92f7c55cc49c85f1ec287260.mp3'),
    ('牺牲', '为了国家利益，他愿意牺牲个人的幸福。', 'hi sinh', 'xī shēng', '为了国家利益，他愿意牺牲个人的幸福。', 'hi sinh', 'xī shēng', 'Wèi le guó jiā lì yì, tā yuàn yì xī shēng gè rén de xìng fú.', 'Vì lợi ích quốc gia, anh ấy sẵn sàng hy sinh hạnh phúc cá nhân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-193c786cfce5cb6fdc77e485.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ea66aac30c6e2d8983ce9d65.mp3'),
    ('熏陶', '他的艺术熏陶使他对绘画产生浓厚兴趣。', 'hun đúc', 'xūn táo', '他的艺术熏陶使他对绘画产生浓厚兴趣。', 'hun đúc', 'xūn táo', 'Tā de yìshù xūntáo shǐ tā duì huìhuà chǎnshēng nónghòu xìngqù.', 'Sự hun đúc nghệ thuật của anh ấy khiến anh ta có hứng thú mạnh mẽ với hội họa.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-9b9072796cd63c66e99ef4fa.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-45fb6a00fd8ccdb2d2000b78.mp3'),
    ('熄灭', '风吹得很大，火焰很快就被熄灭了。', 'dập tắt', 'xī miè', '风吹得很大，火焰很快就被熄灭了。', 'dập tắt', 'xī miè', 'Fēng chuī dé hěn dà, huǒyàn hěn kuài jiù bèi xīmiè le.', 'Gió thổi rất mạnh, ngọn lửa nhanh chóng bị dập tắt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c997b4efd20429e5082a30ca.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-df5f48f527ce32a5c7689011.mp3'),
    ('炫耀', '他喜欢用名牌包来炫耀自己的财富。', 'khoe khoang', 'xuàn yào', '他喜欢用名牌包来炫耀自己的财富。', 'khoe khoang', 'xuàn yào', 'Tā xǐhuān yòng míngpái bāo lái xuànyào zìjǐ de cáifù.', 'Anh ấy thích dùng túi hiệu để khoe khoang sự giàu có của mình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-41486e05de415153f496bf2f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d1d3afb9a7c0fb094b89d3bd.mp3'),
    ('潇洒', '他举止潇洒，给人留下深刻印象。', 'thoải mái', 'xiāo sǎ', '他举止潇洒，给人留下深刻印象。', 'thoải mái', 'xiāo sǎ', 'Tā jǔzhǐ xiāosǎ, gěi rén liú xià shēnkè yìnxiàng.', 'Cử chỉ của anh ấy rất thoải mái, để lại ấn tượng sâu sắc với người khác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0b6d75221bf6b83ba4951f0a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-fef814ea97318b5f14250f8f.mp3'),
    ('溪', '清晨我们沿着小溪散步，感受大自然的美妙。', 'suối', 'xī', '清晨我们沿着小溪散步，感受大自然的美妙。', 'suối', 'xī', 'Qīngchén wǒmen yánzhe xiǎoxī sànbù, gǎnshòu dà zìrán de měimiào.', 'Sáng sớm chúng tôi dạo bộ dọc theo con suối nhỏ, cảm nhận vẻ đẹp của thiên nhiên.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-1f0193a67ca758d59d3e47aa.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-72cec5643a299c3eed21f9b4.mp3'),
    ('消除', '科学技术的发展有助于消除贫困和疾病。', 'loại bỏ, loại trừ', 'xiāo chú', '科学技术的发展有助于消除贫困和疾病。', 'loại bỏ, loại trừ', 'xiāo chú', 'Kēxué jìshù de fāzhǎn yǒu zhù yú xiāochú pínkùn hé jíbìng.', 'Sự phát triển của khoa học kỹ thuật giúp loại bỏ đói nghèo và bệnh tật.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-95aa0ae0444d96faca50514c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-85ad5ee35fac7572970e8ff5.mp3'),
    ('消防', '消防部门迅速赶到现场扑灭火灾，保证安全。', 'chữa cháy', 'xiāo fáng', '消防部门迅速赶到现场扑灭火灾，保证安全。', 'chữa cháy', 'xiāo fáng', 'Xiāofáng bùmén xùnsù gǎndào xiànchǎng pūmiè huǒzāi, bǎozhèng ānquán.', 'Bộ phận chữa cháy nhanh chóng có mặt tại hiện trường để dập tắt đám cháy, đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d992b153e2db1821290cc724.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-4ea4dfcb2e3c13f5ef180827.mp3'),
    ('消耗', '这台机器在运行过程中消耗大量能源。', 'tiêu hao', 'xiāo hào', '这台机器在运行过程中消耗大量能源。', 'tiêu hao', 'xiāo hào', 'Zhè tái jīqì zài yùnxíng guòchéng zhōng xiāohào dàliàng néngyuán.', 'Chiếc máy này tiêu hao một lượng lớn năng lượng trong quá trình vận hành.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0214e71438a47cd0d459b3a0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-af99b70d7eff3984c9685beb.mp3'),
    ('消灭', '政府制定法律以消灭非法行为，保障社会秩序。', 'tiêu diệt', 'xiāo miè', '政府制定法律以消灭非法行为，保障社会秩序。', 'tiêu diệt', 'xiāo miè', 'Zhèngfǔ zhìdìng fǎlǜ yǐ xiāomiè fēifǎ xíngwéi, bǎozhàng shèhuì zhìxù.', 'Chính phủ ban hành pháp luật để tiêu diệt hành vi phạm pháp, bảo đảm trật tự xã hội.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-211e1124539bcb1f7b0c98ad.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6693743dbb02ad45fdc4e075.mp3'),
    ('消毒', '餐具必须经过高温消毒才能使用，确保卫生安全。', 'khử độc', 'xiāo dú', '餐具必须经过高温消毒才能使用，确保卫生安全。', 'khử độc', 'xiāo dú', 'Cānjù bìxū jīngguò gāowēn xiāodú cáinéng shǐyòng, quèbǎo wèishēng ānquán.', 'Bộ đồ ăn phải được khử độc bằng nhiệt độ cao mới được sử dụng, đảm bảo vệ sinh an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c11af6e7553d509b8328847a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-88f75a7c7e9f59e97d86c23c.mp3'),
    ('泄露', '企业要加强保密，防止重要信息泄露。', 'rò rỉ', 'xiè lòu', '企业要加强保密，防止重要信息泄露。', 'rò rỉ', 'xiè lòu', 'Qǐyè yào jiāqiáng bǎomì, fángzhǐ zhòngyào xìnxī xièlòu.', 'Doanh nghiệp cần tăng cường bảo mật để ngăn chặn rò rỉ thông tin quan trọng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-8a3bfabb5516b531a2440eaa.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-7561f00b951c8ba732b5a484.mp3'),
    ('泄气', '遇到挫折时他没有泄气，反而更加努力。', 'nhụt chí, nản lòng', 'xiè qì', '遇到挫折时他没有泄气，反而更加努力。', 'nhụt chí, nản lòng', 'xiè qì', 'Yù dào cuòzhé shí tā méiyǒu xièqì, fǎn''ér gèng jiā nǔlì.', 'Khi gặp thất bại anh ấy không nản lòng mà ngược lại càng cố gắng hơn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-9b7b9861c365dbcb4797535a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-dac9793569b876fdbb6b790d.mp3'),
    ('汹涌', '海浪汹涌澎湃，展现大海的威力和壮观。', 'cuồn cuộn', 'xiōng yǒng', '海浪汹涌澎湃，展现大海的威力和壮观。', 'cuồn cuộn', 'xiōng yǒng', 'Hǎilàng xiōngyǒng péngpài, zhǎnxiàn dàhǎi de wēilì hé zhuànguān.', 'Sóng biển cuồn cuộn dâng trào, thể hiện sức mạnh và vẻ hùng vĩ của đại dương.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-1e68f3d0fc7b174a6e226bcf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b52e023b42a2131d7b7f8121.mp3'),
    ('欣欣向荣', '春天来了，花草树木欣欣向荣，充满生机。', 'phát triển thịnh vượng', 'xīn xīn xiàng róng', '春天来了，花草树木欣欣向荣，充满生机。', 'phát triển thịnh vượng', 'xīn xīn xiàng róng', 'Chūntiān lái le, huācǎo shùmù xīnxīn xiàng róng, chōngmǎn shēngjī.', 'Mùa xuân đến, cây cỏ hoa lá phát triển thịnh vượng, tràn đầy sức sống.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-696dc450c23c072af9e1719f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e10dba3aab9a31ac5f77462f.mp3'),
    ('欣慰', '看到孩子们健康成长，父母感到十分欣慰。', 'mừng vui thanh thản', 'xīn wèi', '看到孩子们健康成长，父母感到十分欣慰。', 'mừng vui thanh thản', 'xīn wèi', 'Kàn dào háizimen jiànkāng chéngzhǎng, fùmǔ gǎndào shífēn xīnwèi.', 'Nhìn thấy con cái lớn lên khỏe mạnh, cha mẹ cảm thấy rất mừng vui thanh thản.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-b9db8ed80280640188e60680.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-48a3bc9a413bcba855acf8bc.mp3'),
    ('显著', '这项技术的进步带来了显著的经济效益。', 'nổi bật, rõ rệt', 'xiǎn zhù', '这项技术的进步带来了显著的经济效益。', 'nổi bật, rõ rệt', 'xiǎn zhù', 'Zhè xiàng jìshù de jìnbù dài lái le xiǎnzhù de jīngjì xiàoyì.', 'Tiến bộ của công nghệ này mang lại hiệu quả kinh tế nổi bật.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c790d53eb12cb5ebd72efc8c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0b314909727c987e5ce0db66.mp3'),
    ('昔日', '昔日的老街区如今已经焕然一新。', 'trước kia', 'xī rì', '昔日的老街区如今已经焕然一新。', 'trước kia', 'xī rì', 'Xīrì de lǎo jiēqū rújīn yǐjīng huànrán yī xīn.', 'Khu phố cũ trước kia giờ đã hoàn toàn đổi mới.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f0b73ea0c02e5828e7e746a9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e1254271ad2115b72269e3a1.mp3'),
    ('旋转', '风车在风中缓缓旋转，景象十分美丽。', 'quay tròn', 'xuán zhuàn', '风车在风中缓缓旋转，景象十分美丽。', 'quay tròn', 'xuán zhuàn', 'Fēngchē zài fēng zhōng huǎnhuǎn xuánzhuǎn, jǐngxiàng shífēn měilì.', 'Cối xay gió trong gió quay tròn chậm rãi, cảnh tượng rất đẹp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-68eb90fa809e72cc1386996b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-17293cfff80e1bcee02964ee.mp3'),
    ('旋律', '这首歌的旋律优美动听，深受大家喜爱。', 'giai điệu', 'xuán lǜ', '这首歌的旋律优美动听，深受大家喜爱。', 'giai điệu', 'xuán lǜ', 'Zhè shǒu gē de xuánlǜ yōuměi dòngtīng, shēnshòu dàjiā xǐ''ài.', 'Giai điệu của bài hát này du dương dễ nghe, được mọi người yêu thích.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f0385d5399ff3c93c55d443b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-4669f697d8869f0fa79e8a35.mp3'),
    ('新颖', '她设计的方案非常新颖，赢得了专家的认可。', 'mới lạ, mới mẻ', 'xīn yǐng', '她设计的方案非常新颖，赢得了专家的认可。', 'mới lạ, mới mẻ', 'xīn yǐng', 'Tā shèjì de fāng''àn fēicháng xīnyǐng, yíngdé le zhuānjiā de rènkě.', 'Bản thiết kế của cô ấy rất mới lạ, được các chuyên gia công nhận.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a8d2ec25498658605cedb94c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-031e49887ecc5c784767b2e6.mp3')
)
update public.cards as card
set
  pinyin = case
    when card.pinyin = repaired.original_pinyin then repaired.pinyin
    else card.pinyin
  end,
  meaning_vi = case
    when card.meaning_vi = repaired.original_meaning_vi then repaired.meaning_vi
    else card.meaning_vi
  end,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.decks as deck,
  repaired_hsk as repaired
where card.deck_id = deck.id
  and card.user_id = deck.user_id
  and (
    deck.source_template_slug = 'hsk6-co-ban'
    or (
      deck.source_template_slug is null
      and deck.name = 'HSK6 cơ bản'
    )
  )
  and card.chinese = repaired.chinese
  and (
    card.example_cn is not distinct from repaired.original_example_cn
    or card.example_cn is null
  );
